<?php require_once __DIR__.'/../config/config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$cid=(int)$_POST['customer_id'];$name=clean_text($_POST['name']??'',160);$status=clean_text($_POST['status']??'Planning',40);$code='PRJ-'.strtoupper(bin2hex(random_bytes(4)));$s=db()->prepare('INSERT INTO projects(project_code,customer_id,name,status,start_date,due_date) VALUES(?,?,?,?,?,?)');$s->execute([$code,$cid,$name,$status,$_POST['start_date']?:null,$_POST['due_date']?:null]);header('Location:projects.php');exit;}$customers=db()->query('SELECT id,business FROM customers ORDER BY business')->fetchAll();$projects=db()->query('SELECT p.*,c.business FROM projects p LEFT JOIN customers c ON c.id=p.customer_id ORDER BY p.created_at DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projects | CRM</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><header class="site-header"><a class="brand" href="index.php"><span class="brand-mark">W</span><span>Web<span>Studio</span></span></a><nav class="nav"><a href="index.php">CRM</a><a href="customers.php">Customers</a><a href="quotes.php">Quotes</a><a href="logout.php">Log out</a></nav></header><main><section class="section"><span class="eyebrow">DELIVERY</span><h1>Projects</h1><div class="card-3d" style="padding:26px;border-radius:24px;max-width:850px"><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars(csrf_token())?>"><div class="form-grid"><div class="field"><label>Customer</label><select name="customer_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=htmlspecialchars($c['business'])?></option><?php endforeach;?></select></div><div class="field"><label>Project name</label><input name="name" required placeholder="Business Website"></div><div class="field"><label>Status</label><select name="status"><option>Planning</option><option>Design</option><option>Development</option><option>Review</option><option>Live</option><option>On Hold</option></select></div><div class="field"><label>Start date</label><input type="date" name="start_date"></div><div class="field"><label>Due date</label><input type="date" name="due_date"></div><div class="field full"><button class="btn btn-3d">Create Project →</button></div></div></form></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Project</th><th>Business</th><th>Name</th><th>Status</th><th>Due</th></tr></thead><tbody><?php foreach($projects as $p):?><tr><td><?=htmlspecialchars($p['project_code'])?></td><td><?=htmlspecialchars($p['business']??'')?></td><td><?=htmlspecialchars($p['name'])?></td><td><span class="status"><?=htmlspecialchars($p['status'])?></span></td><td><?=htmlspecialchars($p['due_date']??'')?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>